SELECT DISTINCT p.id, p.policy_name, p.datasource_id, p.table_name,
       p.column_name, p.filter_type, p.filter_value, p.priority
FROM row_level_policies p
LEFT JOIN row_level_policy_bindings b ON p.id = b.policy_id AND b.is_active = 1
WHERE p.is_active = 1
  AND p.table_name = #{tableName}

      AND (p.datasource_id = #{datasourceId} OR p.datasource_id IS NULL)

  AND (
      b.user_id = #{userId}

          OR b.role_name = #{role}

      OR (b.user_id IS NULL AND b.role_name IS NULL)
  )
ORDER BY p.priority DESC

SELECT DISTINCT p.id, p.policy_name, p.datasource_id, p.table_name, p.column_name, p.filter_type, p.filter_value, p.priority FROM row_level_policies p LEFT JOIN row_level_policy_bindings b ON p.id = b.policy_id AND b.is_active = 1 WHERE p.is_active = 1 AND p.table_name IN
#{tn}
AND (p.datasource_id = #{datasourceId} OR p.datasource_id IS NULL)
AND ( b.user_id = #{userId}
OR b.role_name = #{role}
OR (b.user_id IS NULL AND b.role_name IS NULL) ) ORDER BY p.priority DESC

SELECT p.id, p.policy_name, p.datasource_id, p.table_name, p.column_name, p.filter_type, p.filter_value, p.priority, p.is_active, p.created_at, p.updated_at FROM row_level_policies p
p.datasource_id = #{datasourceId}
ORDER BY p.is_active DESC, p.table_name, p.priority DESC
